            frame_functions_2
	    vector_functions
	    frame_functions_example
	    [ 5, 6 ]

def make_frame(origin, edge1, edge2):
    return pair(origin, pair(edge1, edge2))
def origin_frame(frame):
    return head(frame)
def edge1_frame(frame):
    return head(tail(frame))
def edge2_frame(frame):
    return tail(tail(frame))
